"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5461],{5461:function(e){e.exports=JSON.parse('{"content":"\\n\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/69507b3e7c6bde402ec75d848437ba5c.jpg\\"\\n  title=\\"Canmore Bupyeong Branch\\"\\n  cuisine=\\"Cafe\\"\\n  address=\\"12, Bupyeong-daero, Bupyeong-gu, Incheon\\"\\n  rating=3.5\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\n\\nVisiting Bupyeong after a long time, I saw that the familiar and nostalgic <mark>Canmore</mark> was still alive and running.  \\nWithout hesitation, I went inside with my friends.  \\n\\nRiding on the popularity of nostalgic past relics that I personally find slightly puzzling, `Canmore` is surprisingly a trending hot spot among younger crowds these days.  \\nIndeed, when we visited there was a waiting line, and most customers were quite young.  \\n```adcard\\n```\\nThe nostalgic <mark>swings</mark> were still there just like old times.  \\nThe `snow ice bingsu` and `parfait` were still there too.  \\n\\nThe iconic `unlimited toast refill` from back then was also available as long as each person ordered one item.  \\n\\nIt was wonderful to reminisce and relive memories after a long time.  \\n\\n## Pictures\\n\\n<pictures>\\n<img src=\\"/assets/snippets/location/69507b3e7c6bde402ec75d848437ba5c.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Canmore Bupyeong Branch\\">\\n<img src=\\"/assets/snippets/location/10372f6af71e0d54a7f47d9a3ea6d919.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Canmore Bupyeong Branch\\">\\n<img src=\\"/assets/snippets/location/a96d947976f75a1f94317d36f9841e4c.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Canmore Bupyeong Branch\\">\\n</pictures>\\n"}')}}]);